 EXECUTE $acl_8167$
DO $transport_acl$
DECLARE p record; grant_row record;
BEGIN
 FOR p IN SELECT oid,proowner FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('native_detached_eval_scan','native_detached_eval_field','native_detached_eval_scope','native_detached_eval_domain','native_detached_eval_envelope','native_detached_eval_point_state','native_detached_snapshot','native_detached_lineage') LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',p.oid::regprocedure);
  FOR grant_row IN SELECT DISTINCT a.grantee FROM pg_proc f CROSS JOIN LATERAL aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) a
   WHERE f.oid=p.oid AND a.grantee<>0 AND a.grantee<>p.proowner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',p.oid::regprocedure,pg_get_userbyid(grant_row.grantee));
  END LOOP;
 END LOOP;
END $transport_acl$;

