 SELECT * INTO actual FROM pg_proc WHERE oid='public.application_native_worklist_helpers_current()'::regprocedure;
 IF actual.prosrc IS DISTINCT FROM original_bodies->>'application_native_worklist_helpers_current()' THEN RAISE EXCEPTION 'Detached evaluator transition target changed: %',actual.oid::regprocedure;END IF;
 body:=actual.prosrc;

 SELECT string_agg(format('(%s::oid,%L::text)',p.oid,encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex')),',' ORDER BY p.oid),count(*) INTO pins,pin_count
 FROM jsonb_array_elements_text('["read_entity_derivation_source_before_capture(uuid,text,uuid)","read_entity_derivation_source_before_recordings(uuid,text,uuid)","read_entity_derivation_source_before_browser_profile(uuid,text,uuid)","read_entity_derivation_source_before_browser_session(uuid,text,uuid)","read_entity_derivation_source_before_workflow_run(uuid,text,uuid)","read_entity_derivation_source_before_blueprint(uuid,text,uuid)","read_entity_derivation_source_before_primitive_v2(uuid,text,uuid)","read_entity_derivation_source_before_conversation(uuid,text,uuid)","read_resource_page_dependencies(uuid,text,uuid,text)","read_entity_derivation_source_before_engineering_archive(uuid,text,uuid)","read_entity_derivation_source_before_application_fields(uuid,text,uuid)","read_entity_derivation_source_before_page(uuid,text,uuid)","read_admitted_native_scope_snapshot_before_application_sources(uuid,text,uuid)","read_entity_derivation_source_before_persistent_context(uuid,text,uuid)","application_scope_lineage(uuid,text[],uuid[],text[])","read_admitted_native_scope_snapshot_before_public_share(uuid,text,uuid)","read_admitted_native_scope_snapshot_before_persistent_context(uuid,text,uuid)","read_admitted_native_scope_snapshot_before_knowledge_versions(uuid,text,uuid)","read_entity_derivation_source_before_knowledge_source_parent(uuid,text,uuid)","application_session_query_parent(uuid,uuid)","application_session_eval_scope(uuid,text,uuid,text,jsonb)","application_session_eval_point_state(uuid,text,uuid,text[],jsonb)","application_session_eval_scan(uuid,uuid,text,integer,text[],jsonb,jsonb,jsonb)","application_session_eval_domain(uuid,text,uuid,text[],jsonb)","application_session_eval_envelope(uuid,text,uuid,text,text[],jsonb)","application_session_eval_field(uuid,uuid,text,jsonb)","read_entity_derivation_source_before_knowledge_versions(uuid,text,uuid)","application_scope_source_edges(uuid,text,uuid,text)","read_admitted_native_scope_snapshot(uuid,text,uuid)","read_entity_derivation_source_before_memory_successor(uuid,text,uuid)","application_memory_query_context(uuid)","read_entity_derivation_source(uuid,text,uuid)","application_memory_statement_helpers_current()","application_empty_query_helpers_current()","native_worklist_context(uuid,jsonb)","native_worklist_edges(uuid,jsonb)","native_worklist_page_dependencies(uuid,text,uuid,text,jsonb)","native_worklist_seed(uuid,jsonb)","native_worklist_lineage(uuid,text[],uuid[],text[],jsonb)","native_worklist_snapshot(uuid,text,uuid,text,jsonb)","native_worklist_frame_current(uuid,jsonb)","native_worklist_current(uuid,text,uuid,jsonb)","native_worklist_current_application_sources(uuid,text,uuid,jsonb)","native_worklist_current_knowledge_versions(uuid,text,uuid,jsonb)","native_worklist_current_persistent_context(uuid,text,uuid,jsonb)","native_worklist_current_public_share(uuid,text,uuid,jsonb)","native_worklist_source(uuid,text,uuid,jsonb)","native_worklist_source_application_fields(uuid,text,uuid,jsonb)","native_worklist_source_blueprint(uuid,text,uuid,jsonb)","native_worklist_source_browser_profile(uuid,text,uuid,jsonb)","native_worklist_source_browser_session(uuid,text,uuid,jsonb)","native_worklist_source_capture(uuid,text,uuid,jsonb)","native_worklist_source_conversation(uuid,text,uuid,jsonb)","native_worklist_source_engineering_archive(uuid,text,uuid,jsonb)","native_worklist_source_knowledge_source_parent(uuid,text,uuid,jsonb)","native_worklist_source_knowledge_versions(uuid,text,uuid,jsonb)","native_worklist_source_memory_successor(uuid,text,uuid,jsonb)","native_worklist_source_page(uuid,text,uuid,jsonb)","native_worklist_source_persistent_context(uuid,text,uuid,jsonb)","native_worklist_source_primitive_v2(uuid,text,uuid,jsonb)","native_worklist_source_recordings(uuid,text,uuid,jsonb)","native_worklist_source_workflow_run(uuid,text,uuid,jsonb)","native_worklist_eval_domain(uuid,text,uuid,text[],jsonb)","native_worklist_eval_envelope(uuid,text,uuid,text,text[],jsonb)","native_worklist_eval_field(uuid,uuid,text,jsonb)","native_worklist_eval_point_state(uuid,text,uuid,text[],jsonb)","native_worklist_eval_scan(uuid,uuid,text,integer,text[],jsonb,jsonb,jsonb)","native_worklist_eval_scope(uuid,text,uuid,text,jsonb)","read_native_file_worklist_evidence(uuid,text[],uuid[],text[],boolean,boolean)","native_detached_eval_scan(uuid,uuid,text,integer,text[],jsonb,jsonb,jsonb,jsonb)","native_detached_eval_field(uuid,uuid,text,jsonb,jsonb)","native_detached_eval_scope(uuid,text,uuid,text,jsonb,jsonb)","native_detached_eval_domain(uuid,text,uuid,text[],jsonb,jsonb)","native_detached_eval_envelope(uuid,text,uuid,text,text[],jsonb,jsonb)","native_detached_eval_point_state(uuid,text,uuid,text[],jsonb,jsonb)","native_detached_snapshot(uuid,text,uuid,text,jsonb)","native_detached_lineage(uuid,text[],uuid[],text[],jsonb)"]'::jsonb) r(signature) JOIN pg_proc p ON p.oid=to_regprocedure('public.'||r.signature);
